"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

function GraphCorners({ mark = "+" }: { mark?: string }) {
  return (
    <>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute top-0 left-0 z-10 block -translate-x-1/2 -translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute top-0 right-0 z-10 block translate-x-1/2 -translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute bottom-0 left-0 z-10 block -translate-x-1/2 translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute right-0 bottom-0 z-10 block translate-x-1/2 translate-y-1/2 bg-background px-0.5 text-graph-frame"
      >
        {mark}
      </span>
    </>
  )
}

function GraphTitle({
  className,
  children,
  ...props
}: React.ComponentProps<"figcaption">) {
  return (
    <figcaption
      className={cn(
        "absolute top-0 left-1/2 z-10 -translate-x-1/2 -translate-y-1/2 bg-background px-2.5 tracking-wide whitespace-nowrap uppercase",
        className
      )}
      {...props}
    >
      <span className="graph-title-ink text-graph-accent">[ {children} ]</span>
    </figcaption>
  )
}

function GraphBody({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn("w-max min-w-full px-5 py-7 sm:px-8 sm:py-8", className)}
      {...props}
    />
  )
}

function GraphRule({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      aria-hidden="true"
      className={cn("graph-rule w-full", className)}
      {...props}
    />
  )
}

function GraphTrack({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      aria-hidden="true"
      className={cn("flex w-full min-w-min select-none", className)}
      {...props}
    />
  )
}

function GraphTick({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      className={cn("min-w-[1ch] flex-1 text-center", className)}
      {...props}
    />
  )
}

function Graph({
  title,
  corner = "+",
  className,
  children,
  ...props
}: React.ComponentProps<"figure"> & {
  title?: string
  corner?: string
}) {
  const captionId = React.useId()

  return (
    <figure
      aria-labelledby={title ? captionId : undefined}
      className={cn(
        "relative max-w-full min-w-0 overflow-x-auto overscroll-x-contain graph-frame font-mono text-sm text-foreground",
        className
      )}
      {...props}
    >
      {title ? <GraphTitle id={captionId}>{title}</GraphTitle> : null}
      <GraphCorners mark={corner} />
      {children}
    </figure>
  )
}

export {
  Graph,
  GraphBody,
  GraphCorners,
  GraphRule,
  GraphTick,
  GraphTitle,
  GraphTrack,
}

import type { Transition, Variants } from "motion/react"

export const easeOutCubic = [0.215, 0.61, 0.355, 1] as const

export const DIM_OPACITY = 0.4

export function graphTransition(
  reduce: boolean | null,
  extras?: Transition
): Transition {
  if (reduce) {
    return { duration: 0 }
  }

  return {
    duration: 0.22,
    ease: easeOutCubic,
    ...extras,
  }
}

export function fadeUp(reduce: boolean | null): Variants {
  if (reduce) {
    return {
      hidden: { opacity: 1, transform: "translateY(0px)" },
      show: { opacity: 1, transform: "translateY(0px)" },
    }
  }

  return {
    hidden: { opacity: 0, transform: "translateY(8px)" },
    show: {
      opacity: 1,
      transform: "translateY(0px)",
      transition: graphTransition(false),
    },
  }
}

export function staggerList(reduce: boolean | null, stagger = 0.04): Variants {
  return {
    hidden: {},
    show: {
      transition: reduce ? { duration: 0 } : { staggerChildren: stagger },
    },
  }
}

export function fillDelay(reduce: boolean | null, index: number, step = 0.03) {
  if (reduce) {
    return 0
  }

  return Math.min(index * step, 0.28)
}

export function clamp01(value: number) {
  return Math.min(1, Math.max(0, value))
}

export const GLYPH_SETS = {
  shade: ["·", "░", "▒", "▓", "█"],
  ascii: [".", "-", "=", "#", "@"],
  hash: [".", ":", "+", "#", "█"],
  bar: ["▁", "▂", "▃", "▅", "█"],
} as const

export type GlyphSetName = keyof typeof GLYPH_SETS
export type Glyphs = GlyphSetName | readonly string[]

export const INTENSITY_GLYPHS = GLYPH_SETS.shade

export function resolveGlyphs(glyphs?: Glyphs): readonly string[] {
  if (glyphs == null) {
    return GLYPH_SETS.shade
  }

  if (typeof glyphs === "string") {
    return GLYPH_SETS[glyphs] ?? GLYPH_SETS.shade
  }

  return glyphs.length > 0 ? glyphs : GLYPH_SETS.shade
}

export function trackMarks(
  glyphs?: Glyphs,
  fallback: { empty: string; rest: string; fill: string } = {
    empty: "-",
    rest: "░",
    fill: "█",
  }
) {
  if (glyphs == null) {
    return fallback
  }

  const set = resolveGlyphs(glyphs)
  const last = set.length - 1

  return {
    empty: set[0] ?? fallback.empty,
    rest: set[Math.min(1, last)] ?? fallback.rest,
    fill: set[last] ?? fallback.fill,
  }
}

export function intensityLevel(value: number, max: number) {
  if (value <= 0 || max <= 0) {
    return 0
  }

  return Math.max(1, Math.round(clamp01(value / max) * 4))
}

export function intensityGlyph(
  level: number,
  glyphs: readonly string[] = INTENSITY_GLYPHS
) {
  if (glyphs.length === 0) {
    return "·"
  }

  const clamped = Math.min(4, Math.max(0, Math.round(level)))
  const index = Math.round((clamped / 4) * (glyphs.length - 1))
  return glyphs[index] ?? glyphs[0] ?? "·"
}

export function intensityClass(level: number, palette: GraphPalette = "mono") {
  const index = Math.min(4, Math.max(0, Math.round(level)))

  if (index <= 0) {
    return "text-graph-frame"
  }

  if (palette === "mono") {
    if (index <= 2) {
      return "text-graph-muted"
    }

    if (index === 3) {
      return "text-foreground"
    }

    return "text-graph-accent"
  }

  if (palette === "multi") {
    if (index === 1) {
      return "text-graph-accent-2"
    }

    if (index <= 3) {
      return "text-graph-accent-3"
    }

    return "text-graph-accent"
  }

  if (index <= 2) {
    return "text-graph-accent-2"
  }

  return "text-graph-accent"
}

export type GraphPalette = "mono" | "duo" | "multi"

const SERIES_TONES = [
  "text-graph-accent",
  "text-graph-accent-2",
  "text-graph-accent-3",
] as const

export function isMonoPalette(palette?: GraphPalette) {
  return palette == null || palette === "mono"
}

export function seriesClass(palette: GraphPalette | undefined, index: number) {
  if (isMonoPalette(palette)) {
    return index === 0 ? "text-graph-accent" : "text-foreground"
  }

  const count = palette === "duo" ? 2 : 3
  return SERIES_TONES[index % count]
}

export function seriesDim(
  palette: GraphPalette | undefined,
  highlighted: boolean
) {
  if (!isMonoPalette(palette) || highlighted) {
    return undefined
  }

  return { opacity: DIM_OPACITY }
}

export function toneClass(
  palette: GraphPalette | undefined,
  role: "primary" | "secondary" | "idle" | "empty"
) {
  if (role === "empty") {
    return "text-graph-frame"
  }

  if (role === "idle") {
    return "text-graph-muted"
  }

  if (role === "primary") {
    return "text-graph-accent"
  }

  return isMonoPalette(palette) ? "text-graph-muted" : "text-graph-accent-2"
}

"use client"

import { motion, useReducedMotion } from "motion/react"

import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  intensityClass,
  intensityGlyph,
  intensityLevel,
  resolveGlyphs,
  staggerList,
  type Glyphs,
  type GraphPalette,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
]

const DAY_MS = 86_400_000

type ActivityDay = {
  date: string
  count: number
}

type ActivityCell = {
  date: string
  count: number
  inRange: boolean
}

type GraphActivityProps = {
  title: string
  days: ActivityDay[]
  weekStartsOn?: 0 | 1
  max?: number
  legend?: boolean
  caption?: string | false
  glyphs?: Glyphs
  palette?: GraphPalette
  corner?: string
  className?: string
}

function parseUTC(iso: string) {
  const [year, month, day] = iso.split("-").map(Number)
  return Date.UTC(year, month - 1, day)
}

function toISO(utc: number) {
  return new Date(utc).toISOString().slice(0, 10)
}

function buildWeeks(days: ActivityDay[], weekStartsOn: 0 | 1) {
  if (days.length === 0) {
    return [] as ActivityCell[][]
  }

  const counts = new Map<string, number>()
  let min = Number.POSITIVE_INFINITY
  let max = Number.NEGATIVE_INFINITY

  for (const day of days) {
    const time = parseUTC(day.date)
    counts.set(day.date, day.count)
    if (time < min) min = time
    if (time > max) max = time
  }

  const lead = (new Date(min).getUTCDay() - weekStartsOn + 7) % 7
  const trail = (weekStartsOn + 6 - new Date(max).getUTCDay() + 7) % 7
  const first = min - lead * DAY_MS
  const last = max + trail * DAY_MS
  const weeks: ActivityCell[][] = []
  let week: ActivityCell[] = []

  for (let time = first; time <= last; time += DAY_MS) {
    const date = toISO(time)
    const inRange = time >= min && time <= max
    week.push({
      date,
      count: inRange ? (counts.get(date) ?? 0) : 0,
      inRange,
    })
    if (week.length === 7) {
      weeks.push(week)
      week = []
    }
  }

  return weeks
}

function monthLabels(weeks: ActivityCell[][]) {
  return weeks.map((week) => {
    const start = week.find((cell) => {
      if (!cell.inRange) {
        return false
      }

      return new Date(parseUTC(cell.date)).getUTCDate() === 1
    })

    if (!start) {
      return ""
    }

    return MONTHS[new Date(parseUTC(start.date)).getUTCMonth()] ?? ""
  })
}

function dayLabels(weekStartsOn: 0 | 1) {
  return weekStartsOn === 1
    ? ["M", "", "W", "", "F", "", ""]
    : ["", "M", "", "W", "", "F", ""]
}

function IntensityScale({
  glyphs,
  palette,
}: {
  glyphs: readonly string[]
  palette?: GraphPalette
}) {
  return (
    <p className="flex items-center gap-2 text-graph-muted">
      <span>Less</span>
      <span aria-hidden="true" className="flex select-none">
        {glyphs.map((glyph, index) => (
          <span
            className={cn(
              "w-[1ch] text-center",
              intensityClass(
                Math.round((index / Math.max(glyphs.length - 1, 1)) * 4),
                palette
              )
            )}
            key={`${glyph}-${index}`}
          >
            {glyph}
          </span>
        ))}
      </span>
      <span>More</span>
    </p>
  )
}

function GraphActivity({
  title,
  days,
  weekStartsOn = 0,
  max,
  legend = true,
  caption,
  glyphs,
  palette,
  corner,
  className,
}: GraphActivityProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.01)
  const weeks = buildWeeks(days, weekStartsOn)
  const months = monthLabels(weeks)
  const labels = dayLabels(weekStartsOn)
  const peak = max ?? Math.max(0, ...days.map((day) => day.count), 0)
  const total = days.reduce((sum, day) => sum + day.count, 0)
  const summary = `${total.toLocaleString("en-US")} contributions`
  const set = resolveGlyphs(glyphs)
  const quiet = set[0] ?? "·"

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody className="flex flex-col gap-4">
        <div className="flex w-max min-w-full flex-col gap-1">
          <div className="flex h-[1.25em] w-max min-w-full">
            <span className="w-[2ch] shrink-0" />
            {months.map((month, index) => (
              <span className="relative min-w-[1ch] flex-1" key={`m-${index}`}>
                {month ? (
                  <span className="absolute bottom-0 left-0 whitespace-nowrap text-graph-muted">
                    {month}
                  </span>
                ) : null}
              </span>
            ))}
          </div>
          <div className="flex w-max min-w-full">
            <div className="flex w-[2ch] shrink-0 flex-col">
              {labels.map((label, index) => (
                <span
                  className="flex h-[1.15em] items-center text-graph-muted"
                  key={`d-${index}`}
                >
                  {label}
                </span>
              ))}
            </div>
            <motion.div
              className="flex w-max min-w-0 flex-1"
              initial={reduce ? false : "hidden"}
              variants={list}
              viewport={{ once: true, amount: 0.2 }}
              whileInView="show"
            >
              {weeks.map((week, weekIndex) => (
                <motion.div
                  className={cn(
                    "flex w-[1ch] min-w-[1ch] flex-1 flex-col",
                    !reduce && "will-change-[transform,opacity]"
                  )}
                  key={week[0]?.date ?? weekIndex}
                  variants={item}
                >
                  {week.map((cell) => {
                    const level = cell.inRange
                      ? intensityLevel(cell.count, peak)
                      : 0

                    return (
                      <span
                        aria-hidden="true"
                        className={cn(
                          "flex h-[1.15em] w-full items-center justify-center leading-none select-none",
                          cell.inRange
                            ? intensityClass(level, palette)
                            : "text-transparent"
                        )}
                        key={cell.date}
                      >
                        {cell.inRange ? intensityGlyph(level, set) : quiet}
                      </span>
                    )
                  })}
                </motion.div>
              ))}
            </motion.div>
          </div>
        </div>
        {caption === false && !legend ? null : (
          <div
            className={cn(
              "flex flex-wrap items-center gap-3",
              caption === false ? "justify-end" : "justify-between"
            )}
          >
            {caption === false ? null : (
              <p className="text-graph-muted tabular-nums">
                {caption ?? summary}
              </p>
            )}
            {legend ? <IntensityScale glyphs={set} palette={palette} /> : null}
          </div>
        )}
        <span className="sr-only">
          {total} contributions across {days.length} days
          {caption ? `. ${caption}` : ""}
        </span>
      </GraphBody>
    </Graph>
  )
}

export { GraphActivity }
export type { ActivityDay, GraphActivityProps }
